/* Scripted demo tour — open the site with ?demo=1 to auto-play (used to record the < 3 min video).
 *
 * Timing is driven by the narration: web/demo_timing.js (generated by scripts/make_voice.py from
 * video/narration.json) gives each segment's voice-clip length. Segment i starts at
 *   leadIn + sum(duration[0..i-1] + gap)
 * which is the same timeline ffmpeg uses to lay the voice clips under the recording, so captions,
 * visuals and voice stay in sync without recording audio in the browser.
 *
 * Every map step drives the real UI and real Amazon Location calls.
 * Options: ?demo=1&voice=1 also plays the clips in the page (for previewing with sound).
 */
(() => {
  "use strict";
  const qs = new URLSearchParams(location.search);
  if (!qs.has("demo")) return;

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const $ = (s) => document.querySelector(s);
  const T = window.MP_DEMO_TIMING || { gap: 0.45, leadIn: 1, segments: {} };
  const WALL = ["01-202-A-01", "04-100-A-01", "09-206-A-01", "20-202-A-01", "23-100-A-01", "26-100-A-01",
                "27-100-A-01", "28-201-A-01", "29-201-A-01", "34-100-A-01", "43-100-A-01", "47-201-A-01"];

  /* ---------- original artwork ----------
   * The video must not contain third-party copyrighted material or trademarks, so the demo never shows
   * official card art. These covers are drawn here from simple geometry: rings, spokes, petals, waves.
   * The live site (without ?demo) still shows the official image from the official server in its popup. */
  const PALETTES = [
    ["#2f6db5", "#9fd3f0", "#f2f2ea"], ["#c8402f", "#f5c542", "#2b2b2b"], ["#3f8f5a", "#c7e59a", "#f4efe2"],
    ["#d9658a", "#ffd1dc", "#f7f3ea"], ["#6b4fa0", "#d8c7f0", "#f4c25b"], ["#e07b28", "#ffe0a8", "#2f3a4a"],
  ];
  function rng(seed) { let s = 0; for (const c of String(seed)) s = (s * 31 + c.charCodeAt(0)) >>> 0; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32); }
  function lidSVG(seed, size = 200) {
    const r = rng(seed), [a, b, c] = PALETTES[Math.floor(r() * PALETTES.length)], kind = Math.floor(r() * 4);
    const N = 6 + Math.floor(r() * 7), parts = [];
    if (kind === 0) for (let i = 0; i < N; i++) {           // 花瓣
      const t = (i / N) * 360;
      parts.push(`<ellipse cx="50" cy="31" rx="9" ry="17" fill="${i % 2 ? a : b}" transform="rotate(${t} 50 50)"/>`);
    } else if (kind === 1) for (let i = 0; i < 5; i++) {    // 波浪
      const y = 30 + i * 9;
      parts.push(`<path d="M10 ${y} q10 -7 20 0 t20 0 t20 0 t20 0" fill="none" stroke="${i % 2 ? a : b}" stroke-width="4" stroke-linecap="round"/>`);
    } else if (kind === 2) for (let i = 0; i < N * 2; i++) { // 放射
      parts.push(`<path d="M50 50 L${50 + 40 * Math.cos((i / N) * Math.PI)} ${50 + 40 * Math.sin((i / N) * Math.PI)}" stroke="${i % 2 ? a : b}" stroke-width="5"/>`);
    } else for (let x = 0; x < 7; x++) for (let y = 0; y < 7; y++) { // 格纹
      if ((x - 3) ** 2 + (y - 3) ** 2 > 10) continue;
      parts.push(`<rect x="${17 + x * 9.5}" y="${17 + y * 9.5}" width="7" height="7" rx="1.5" fill="${(x + y) % 2 ? a : b}"/>`);
    }
    return `<svg viewBox="0 0 100 100" width="${size}" height="${size}" aria-hidden="true">
      <defs><radialGradient id="g${seed}" cx="40%" cy="35%"><stop offset="0" stop-color="#6d737a"/><stop offset="1" stop-color="#2d3135"/></radialGradient>
      <clipPath id="c${seed}"><circle cx="50" cy="50" r="38"/></clipPath></defs>
      <circle cx="50" cy="50" r="48" fill="url(#g${seed})"/><circle cx="50" cy="50" r="44" fill="none" stroke="#1d2023" stroke-width="2"/>
      ${Array.from({ length: 36 }, (_, i) => `<circle cx="${50 + 46 * Math.cos(i / 36 * 2 * Math.PI)}" cy="${50 + 46 * Math.sin(i / 36 * 2 * Math.PI)}" r="0.9" fill="#888e94"/>`).join("")}
      <circle cx="50" cy="50" r="38" fill="${c}"/><g clip-path="url(#c${seed})">${parts.join("")}</g>
      <circle cx="50" cy="50" r="38" fill="none" stroke="#1d2023" stroke-width="2.5"/>
      <circle cx="50" cy="50" r="8" fill="#2d3135" stroke="${a}" stroke-width="2"/></svg>`;
  }
  // 原创卡片：自定义版式，不使用官方卡面的设计与标志
  function cardHTML(id, w = 200, delay = 0) {
    const f = MP.S.all.find((x) => x.properties.id === id), p = f?.properties || {};
    const [col] = PALETTES[Math.floor(rng(id)() * PALETTES.length)];
    const [lon, lat] = f?.geometry.coordinates || [0, 0];
    return `<div class="mcard" style="width:${w}px;transition-delay:${delay}s;--c:${col}">
      <div class="mh"><small>${p.pref || ""}</small><b>${p.muni || ""}</b></div>
      <div class="mi">${lidSVG(id, w - 30)}</div>
      <div class="mf"><span>SERIES ${p.series ?? ""}</span><span>${lat.toFixed(2)}°N ${lon.toFixed(2)}°E</span></div></div>`;
  }
  window.MP_POPUP_ART = (p) => `<div style="display:grid;place-items:center;gap:6px">${lidSVG(p.id, 150)}
    <small style="font:11px 'Azeret Mono',monospace;color:#9a958b">illustration · official card art at gk-p.jp</small></div>`;

  // ---------- overlay styles ----------
  const css = document.createElement("style");
  css.textContent = `
    .demo-cap { position: fixed; left: calc((100vw - 410px) / 2); bottom: 44px; transform: translateX(-50%); z-index: 60; width: min(900px, calc(100vw - 500px));
      background: #0d0e0fea; border: 1px solid #3a3f45; border-left: 4px solid #e8502d; border-radius: 12px;
      padding: 14px 22px; font: 500 22px/1.45 "Zen Kaku Gothic New", sans-serif; color: #ece6da; box-shadow: 0 12px 40px #000c;
      opacity: 0; transition: opacity .3s; }
    .demo-cap.on { opacity: 1; }
    .demo-cap.full { left: 50%; width: min(1100px, calc(100vw - 160px)); }
    .demo-cap b { color: #e8502d; font-weight: 700; }
    .demo-cap i { font-style: normal; color: #d9a441; }
    .demo-cap code { font: 600 18px "Azeret Mono", monospace; color: #d9a441; }

    .demo-stage { position: fixed; inset: 0; z-index: 50; overflow: hidden; pointer-events: none; opacity: 0; transition: opacity .7s;
      background: radial-gradient(ellipse at 50% 35%, #23272b, #0b0c0d 75%); color: #ece6da; font-family: "Zen Kaku Gothic New", sans-serif; }
    .demo-stage.on { opacity: 1; }
    .demo-stage::before { content: ""; position: absolute; inset: 0; opacity: .045;
      background-image: repeating-linear-gradient(45deg, #fff 0 1px, transparent 1px 11px), repeating-linear-gradient(-45deg, #fff 0 1px, transparent 1px 11px); }
    .demo-stage .scene { position: absolute; inset: 0; display: grid; place-items: center; opacity: 0; transition: opacity .7s, transform 1.2s cubic-bezier(.2,.8,.2,1); }
    .demo-stage .scene.on { opacity: 1; }

    /* 原创卡片 */
    .mcard { background: #f4efe2; border-radius: 12px; padding: 0 0 10px; box-shadow: 0 18px 40px #000c; overflow: hidden; color: #222;
      opacity: 0; transform: translateY(30px); transition: opacity .6s, transform .8s cubic-bezier(.2,.8,.2,1); }
    .scene.on .mcard { opacity: 1; transform: none; }
    .mcard .mh { background: var(--c); color: #fff; padding: 8px 12px 7px; text-align: center; }
    .mcard .mh small { display: block; font: 600 11px "Zen Kaku Gothic New"; opacity: .85; }
    .mcard .mh b { font: 800 20px "Shippori Mincho B1", serif; }
    .mcard .mi { display: grid; place-items: center; padding: 12px 0 6px; background: repeating-linear-gradient(45deg, #e9e3d4 0 6px, #efe9dc 6px 12px); }
    .mcard .mf { display: flex; justify-content: space-between; padding: 6px 12px 0; font: 600 10.5px "Azeret Mono", monospace; color: #555; }

    /* 卡墙 */
    .wall { display: grid; grid-template-columns: repeat(6, 200px); gap: 22px; transform: rotate(-4deg) translateY(-90px); transition: transform 7s ease-out; }
    .wall-title { position: absolute; left: 0; right: 0; bottom: 0; padding: 90px 90px 150px; background: linear-gradient(transparent, #0b0c0df2 40%);
      font: 800 64px/1.05 "Shippori Mincho B1", serif; text-shadow: 0 6px 30px #000; }
    .wall-title span { color: #e8502d; }

    /* 单卡特写 */
    .focus { display: grid; grid-template-columns: 420px 520px; gap: 70px; align-items: center; }
    .focus .mcard { transform: rotate(-3deg); box-shadow: 0 30px 70px #000d; }
    .scene.on .focus .mcard { transform: rotate(-3deg); }
    .focus .mcard .mh b { font-size: 34px; } .focus .mcard .mh small { font-size: 15px; } .focus .mcard .mf { font-size: 15px; }
    .focus ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 22px; }
    .focus li { font-size: 26px; line-height: 1.4; display: grid; grid-template-columns: 54px 1fr; align-items: start; opacity: 0; transform: translateX(20px); transition: .6s; }
    .scene.on .focus li { opacity: 1; transform: none; }
    .focus li b { display: block; font: 800 30px "Shippori Mincho B1", serif; color: #ece6da; }
    .focus li small { color: #9a958b; font-size: 19px; }
    .focus .ic { width: 42px; height: 42px; border-radius: 50%; background: #e8502d22; border: 2px solid #e8502d; display: grid; place-items: center; font: 700 18px "Azeret Mono"; color: #e8502d; }

    /* 规则 */
    .rule { text-align: center; }
    .rule .nos { display: flex; gap: 28px; justify-content: center; margin-bottom: 46px; }
    .rule .no { width: 230px; padding: 26px 0; border: 2px solid #3a3f45; border-radius: 18px; font: 600 24px "Zen Kaku Gothic New"; color: #9a958b; position: relative; background: #141618; }
    .rule .no::after { content: ""; position: absolute; left: 20px; right: 20px; top: 50%; height: 4px; background: #e8502d; transform: rotate(-12deg) scaleX(0); transition: transform .5s; border-radius: 4px; }
    .scene.on .rule .no::after { transform: rotate(-12deg) scaleX(1); }
    .scene.on .rule .no:nth-child(2)::after { transition-delay: .4s; } .scene.on .rule .no:nth-child(3)::after { transition-delay: .8s; }
    .rule .yes { display: inline-flex; align-items: center; gap: 22px; padding: 22px 40px; border-radius: 999px; background: #e8502d; color: #fff; font: 800 36px "Shippori Mincho B1", serif;
      box-shadow: 0 0 0 10px #e8502d22, 0 20px 50px #000a; opacity: 0; transition: opacity .6s 1.4s; }
    .scene.on .rule .yes { opacity: 1; }
    .rule .yes span { font: 600 18px "Azeret Mono"; background: #0005; padding: 6px 12px; border-radius: 999px; }

    /* 游客理由 */
    .why { display: grid; grid-template-columns: repeat(3, 360px); gap: 30px; }
    .why > div { background: #141618; border: 1px solid #3a3f45; border-radius: 22px; padding: 32px 30px; opacity: 0; transform: translateY(30px); transition: .7s; }
    .scene.on .why > div { opacity: 1; transform: none; }
    .scene.on .why > div:nth-child(2) { transition-delay: .7s; } .scene.on .why > div:nth-child(3) { transition-delay: 1.4s; }
    .why .n { font: 800 58px/1 "Shippori Mincho B1", serif; color: #e8502d; }
    .why b { display: block; font: 700 27px "Zen Kaku Gothic New"; margin: 14px 0 8px; }
    .why p { margin: 0; color: #cfc8ba; font-size: 20px; line-height: 1.5; }

    /* 问题：47 页地址 */
    .pages { position: relative; width: 1100px; height: 640px; }
    .pages .pg { position: absolute; width: 420px; padding: 22px 24px; background: #ece6da; color: #222; border-radius: 6px; box-shadow: 0 20px 50px #000c;
      font: 15px/1.75 "Zen Kaku Gothic New"; }
    .pages .pg b { font-size: 18px; display: block; margin-bottom: 6px; color: #8a2a12; }
    .pages .tag { position: absolute; right: 30px; bottom: 30px; font: 800 64px/1 "Shippori Mincho B1", serif; color: #e8502d; text-shadow: 0 8px 30px #000; text-align: right; }
    .pages .tag small { display: block; font: 600 24px "Azeret Mono"; color: #ece6da; margin-top: 10px; }

    /* 标题 / 片尾 */
    .title { text-align: center; }
    .title .lid { width: 120px; height: 120px; margin: 0 auto 30px; border-radius: 50%; background: repeating-conic-gradient(#3b4046 0 10deg, #2b2f34 10deg 20deg);
      box-shadow: inset 0 0 0 8px #4b5158, inset 0 0 0 14px #1b1d20, 0 10px 40px #000; display: grid; place-items: center; animation: spin 30s linear infinite; }
    .title .lid span { width: 44px; height: 44px; border-radius: 50%; background: #e8502d; box-shadow: 0 0 0 8px #1b1d20, 0 0 40px #e8502d; }
    .title h1 { font: 800 92px/1.05 "Shippori Mincho B1", serif; margin: 0; }
    .title h1 span { color: #e8502d; }
    .title p { font-size: 30px; color: #cfc8ba; margin: 18px 0 0; }
    .title .k { font: 600 22px/1.7 "Azeret Mono", monospace; color: #d9a441; margin-top: 34px; }

    /* 架构 */
    .arch h2 { font: 800 58px "Shippori Mincho B1", serif; margin: 0 0 40px; text-align: center; }
    .arch .row { display: grid; grid-template-columns: repeat(5, 290px); gap: 26px; }
    .arch .box { border: 1px solid #3a3f45; border-radius: 18px; padding: 22px; background: #141618; position: relative; opacity: 0; transform: translateY(20px); transition: .6s; }
    .scene.on .arch .box { opacity: 1; transform: none; }
    ${[1, 2, 3, 4, 5].map((i) => `.scene.on .arch .box:nth-child(${i}) { transition-delay: ${(i - 1) * 1.9}s; }`).join("\n")}
    .arch .box:not(:last-child)::after { content: "→"; position: absolute; right: -22px; top: 44%; color: #e8502d; font-size: 26px; }
    .arch i { display: block; font: 600 14px "Azeret Mono"; color: #e8502d; font-style: normal; letter-spacing: .06em; }
    .arch b { display: block; font: 700 24px "Zen Kaku Gothic New"; margin: 8px 0; }
    .arch p { margin: 0; color: #cfc8ba; font-size: 18px; line-height: 1.5; }
    .arch code { font: 600 15px "Azeret Mono"; color: #d9a441; }
    .arch .foot { text-align: center; margin-top: 40px; font: 600 22px "Azeret Mono"; color: #d9a441; }
  `;
  document.head.appendChild(css);
  const cap = Object.assign(document.createElement("div"), { className: "demo-cap" });
  const stage = Object.assign(document.createElement("div"), { className: "demo-stage on" });
  document.body.append(stage, cap);

  // ---------- helpers ----------
  function caption(html, full = false) {
    cap.classList.remove("on");
    if (!html) return;
    setTimeout(() => { cap.innerHTML = html; cap.classList.toggle("full", full); cap.classList.add("on"); }, 220);
  }
  function scene(html) {
    stage.classList.add("on");
    const old = stage.querySelectorAll(".scene");
    old.forEach((s) => { s.classList.remove("on"); setTimeout(() => s.remove(), 800); });
    const el = Object.assign(document.createElement("div"), { className: "scene", innerHTML: html });
    stage.appendChild(el);
    requestAnimationFrame(() => requestAnimationFrame(() => el.classList.add("on")));
    return el;
  }
  const hideStage = () => stage.classList.remove("on");
  const fly = (center, zoom, duration = 2500) => MP.map.flyTo({ center, zoom, duration, essential: true });
  const byId = (id) => MP.S.all.find((f) => f.properties.id === id);
  async function placeSearch(q, bias) {
    const r = await window.MP_POST(`${MP_CONFIG.proxyUrl.replace(/\/$/, "")}/search-text`, { QueryText: q, BiasPosition: bias });
    return r.ResultItems[0];
  }

  // ---------- scenes (keyed by narration.json "scene") ----------
  const SCENES = {
    "intro-cover": () => {
      const el = scene(`<div class="wall">${WALL.map((id, i) => cardHTML(id, 200, i * 0.12)).join("")}</div>
        <div class="wall-title">15,000,000 <span>manhole covers</span></div>`);
      setTimeout(() => (el.querySelector(".wall").style.transform = "rotate(-4deg) translate(-40px, -110px) scale(1.06)"), 300);
    },
    "intro-card": () => scene(`<div class="focus">${cardHTML("28-201-A-01", 420)}
        <ul>
          <li><span class="ic">01</span><div><b>Free</b><small>Issued by local sewer agencies since 2016</small></div></li>
          <li style="transition-delay:.5s"><span class="ic">02</span><div><b>The real cover</b><small>Photo, design story, and GPS coordinates on the back</small></div></li>
          <li style="transition-delay:1s"><span class="ic">03</span><div><b>1,313 designs</b><small>29 series, all 47 prefectures</small></div></li>
        </ul></div>`),
    "intro-rule": () => scene(`<div class="rule"><div class="nos"><div class="no">Buy</div><div class="no">Mail order</div><div class="no">Trade online</div></div>
        <div class="yes">Show up in person <span>one counter · one town</span></div></div>`),
    "intro-why": () => scene(`<div class="why">
        <div><div class="n">¥0</div><b>A free souvenir</b><p>Every card is free: one per person, at the counter.</p></div>
        <div><div class="n">1,313</div><b>Off the tourist trail</b><p>Each one is a reason to visit a real town you'd never have picked.</p></div>
        <div><div class="n">536</div><b>On your way anyway</b><p>Tourist offices, roadside stations and museums: stops you'd make regardless.</p></div></div>`),
    "intro-problem": () => {
      const rows = (n) => Array.from({ length: n }, () => "札幌市｜札幌市下水道科学館｜北海道札幌市北区麻生町8｜9:30～17:00（月曜休館）").join("<br>");
      scene(`<div class="pages">
        ${[[40, 60, -6], [230, 20, 3], [420, 90, -2], [610, 40, 5]].map(([l, t, r], i) =>
          `<div class="pg" style="left:${l}px;top:${t}px;transform:rotate(${r}deg)"><b>${["北海道", "京都府", "大阪府", "沖縄県"][i]}のマンホールカード</b>${rows(9)}</div>`).join("")}
        <div class="tag">No map.<small>47 pages · free-text addresses</small></div></div>`);
    },
    title: () => scene(`<div class="title"><div class="lid"><span></span></div>
        <h1>Manhole Pilgrim <span>蓋めぐり</span></h1><p>Every manhole card in Japan, on one map.</p></div>`),

    "map-overview": () => { hideStage(); MP.resetFilters(); MP.render(); MP.selectTab($("#t-explore")); fly([137.6, 37.4], 4.7, 1800); },
    timeline: () => MP.startPlay(Math.floor(((T.segments.s08 ?? 8) * 1000 - 600) / MP.S.maxSeries)),
    popup: async () => {
      MP.stopPlay();
      const f = byId("26-100-A-01");
      fly(f.geometry.coordinates, 13.5, 2000); await sleep(2100); MP.openPopup([f]);
    },
    "sewer-filter": () => {
      MP.closePopup(); MP.resetFilters(); MP.S.ptypes = new Set(["sewer"]); MP.syncChips(); MP.render(); fly([137.6, 37.4], 4.7, 2000);
    },
    "plan-kyoto-iso": async () => {
      MP.resetFilters(); MP.render(); MP.selectTab($("#t-plan"));
      $("#start-q").value = "京都駅";
      document.querySelector('input[name="budget"][value="3600"]').checked = true;
      const it = await placeSearch("京都駅", [135.76, 34.99]);
      await MP.setOrigin(it.Position, it.Title);
    },
    "plan-kyoto-route": () => MP.planRoute(),
    "plan-sapporo": async () => {
      $("#start-q").value = "札幌駅";
      document.querySelector('input[name="budget"][value="7200"]').checked = true;
      await MP.setOrigin([141.35075, 43.06859], "札幌駅");
      await MP.planRoute();
    },
    "disc-lonely": async () => {
      MP.resetFilters(); MP.render(); MP.selectTab($("#t-discover"));
      MP.S.insights[3].go();
    },
    "disc-border": () => { MP.closePopup(); MP.S.insights[4].go(); },
    "disc-roadside": () => { MP.closePopup(); MP.S.insights[6].go(); },
    arch: () => scene(`<div class="arch"><h2>How it works</h2><div class="row">
        <div class="box"><i>SOURCE</i><b>GKP registry</b><p>47 prefecture pages, scraped politely and cached</p></div>
        <div class="box"><i>AMAZON LOCATION</i><b>Places</b><p><code>Geocode</code> + <code>SearchText</code><br>IntendedUse = Storage<br>1,304 / 1,313 precise</p></div>
        <div class="box"><i>APACHE ICEBERG · S3</i><b>Athena MERGE</b><p>One snapshot per series<br><code>FOR VERSION AS OF</code></p></div>
        <div class="box"><i>AWS AMPLIFY</i><b>Static site</b><p>GeoJSON exported from Iceberg, on CloudFront<br>Browser key: <code>GetTile</code> only</p></div>
        <div class="box"><i>API GATEWAY + LAMBDA</i><b>Location proxy</b><p>Isolines · OptimizeWaypoints · RouteMatrix · SearchText<br>rate limit · Japan-only · daily caps</p></div>
      </div><div class="foot">+ Amazon Polly for this narration · DynamoDB for the quota counter</div></div>`),
    iceberg: () => {
      hideStage(); MP.closePopup(); MP.resetFilters(); MP.selectTab($("#t-explore"));
      MP.S.series = 1; $("#series").value = 1; MP.render(); fly([137.6, 37.4], 4.7, 1200);
      setTimeout(() => { MP.S.series = MP.S.maxSeries; $("#series").value = MP.S.maxSeries; MP.render(); }, 3800);
    },
    outro: () => scene(`<div class="title"><div class="lid"><span></span></div><h1>Manhole Pilgrim <span>蓋めぐり</span></h1>
        <p>Go find the sewers.</p>
        <div class="k">main.d1y4wxk0wltj16.amplifyapp.com<br>github.com/cnusergroup/manhole-pilgrim</div></div>`),
  };
  const FULL = new Set(["intro-cover", "intro-card", "intro-rule", "intro-why", "intro-problem", "title", "arch", "outro"]);

  // ---------- run ----------
  async function tour(segments) {
    const voice = qs.has("voice");
    window.__demoLog = [];
    scene(""); // 黑场
    stage.style.transition = "none"; // t=0 立即变黑，便于对齐
    window.__demoStart = performance.now();
    requestAnimationFrame(() => (stage.style.transition = ""));
    const t0 = window.__demoStart + T.leadIn * 1000;
    let at = 0;
    for (const seg of segments) {
      const dur = T.segments[seg.id] ?? 5;
      const wait = t0 + at * 1000 - performance.now();
      if (wait > 0) await sleep(wait);
      window.__demoLog.push([seg.id, Math.round(performance.now() - window.__demoStart)]);
      const fn = SCENES[seg.scene];
      Promise.resolve().then(() => fn && fn()).catch((e) => console.error(seg.scene, e));
      let text = seg.caption;
      if (text && text.includes("{reach}")) {
        // 等可达圈计算出来再显示真实数字
        text = null;
        (async () => { for (let i = 0; i < 40 && !MP.S.reach; i++) await sleep(150); caption(seg.caption.replace("{reach}", MP.S.reach?.length ?? "~100")); })();
      }
      if (text !== null) caption(text, FULL.has(seg.scene));
      if (voice) new Audio(`demo_voice/${seg.id}.mp3`).play().catch(() => {});
      at += dur + T.gap;
    }
    await sleep((T.segments[segments.at(-1).id] ?? 3) * 1000 + 2500);
    window.__demoDone = true;
  }

  // ?demo=1&cover=1 → 静态封面（文章 / 社交预览用），不播放演示
  async function cover() {
    const { map } = MP;
    stage.classList.remove("on");
    document.querySelector("#panel").style.display = "none";
    document.querySelector(".brand").style.display = "none";
    document.querySelectorAll(".maplibregl-ctrl").forEach((c) => (c.style.display = "none"));
    MP.S.series = MP.S.maxSeries - 1; MP.render(); // 只让最新一弾发光，避免画面太乱
    MP.S.series = MP.S.maxSeries; MP.render();
    const W = innerWidth, H = innerHeight;
    map.jumpTo({ center: [136.6, 37.4], zoom: Math.log2(W / 1600) + 4.75 });
    map.setPadding({ left: W * 0.42, top: 0, right: 0, bottom: 0 });
    const el = document.createElement("div");
    el.className = "cover";
    el.innerHTML = `
      <div class="cv-copy">
        <div class="cv-lid"><span></span></div>
        <h1>Manhole Pilgrim<br><span>蓋めぐり</span></h1>
        <p>Every Japanese manhole card on one map.<br>How many can you collect this weekend?</p>
        <div class="cv-stats"><b>1,313</b> cards <i>·</i> <b>47</b> prefectures <i>·</i> <b>10</b> years</div>
        <div class="cv-aws">Amazon Location Service · Apache Iceberg on Amazon S3</div>
      </div>
      <div class="cv-cards">${["28-201-A-01", "01-202-A-01", "47-201-A-01"].map((id, i) => `<div class="cv-c" style="--i:${i}">${cardHTML(id, 190)}</div>`).join("")}</div>`;
    const css2 = document.createElement("style");
    css2.textContent = `
      .cover { position: fixed; inset: 0; z-index: 70; pointer-events: none;
        background: linear-gradient(90deg, #0b0c0d 0%, #0b0c0df2 30%, #0b0c0d99 44%, transparent 60%); }
      .cv-copy { position: absolute; left: 7%; top: 50%; transform: translateY(-52%); color: #ece6da; max-width: 46%; }
      .cv-lid { width: 92px; height: 92px; border-radius: 50%; margin-bottom: 28px; background: repeating-conic-gradient(#3b4046 0 10deg, #2b2f34 10deg 20deg);
        box-shadow: inset 0 0 0 6px #4b5158, inset 0 0 0 11px #1b1d20, 0 10px 40px #000; display: grid; place-items: center; }
      .cv-lid span { width: 34px; height: 34px; border-radius: 50%; background: #e8502d; box-shadow: 0 0 0 7px #1b1d20, 0 0 34px #e8502d; }
      .cover h1 { font: 800 96px/1.02 "Shippori Mincho B1", serif; margin: 0; letter-spacing: -.01em; }
      .cover h1 span { color: #e8502d; font-size: 78px; }
      .cover p { font: 500 30px/1.45 "Zen Kaku Gothic New", sans-serif; color: #cfc8ba; margin: 26px 0 0; }
      .cv-stats { margin-top: 30px; font: 500 26px "Zen Kaku Gothic New"; color: #cfc8ba; }
      .cv-stats b { font: 800 40px "Shippori Mincho B1", serif; color: #ece6da; } .cv-stats i { color: #e8502d; font-style: normal; margin: 0 8px; }
      .cv-aws { margin-top: 22px; display: inline-block; font: 600 19px "Azeret Mono", monospace; color: #d9a441; border: 1px solid #d9a44166; border-radius: 999px; padding: 9px 18px; }
      .cv-cards { position: absolute; right: 7%; bottom: 9%; width: 440px; height: 300px; zoom: .74; }
      .cv-c { position: absolute; bottom: 0; left: calc(var(--i) * 118px); transform: rotate(calc((var(--i) - 1) * 9deg)) translateY(calc(var(--i) * -6px)); transform-origin: 50% 120%; }
      .cv-c .mcard { opacity: 1; transform: none; }`;
    document.head.appendChild(css2);
    document.body.appendChild(el);
    await new Promise((r) => map.once("idle", r));
    window.__coverReady = true;
  }

  window.addEventListener("mp:ready", async () => {
    if (qs.has("cover")) return cover();
    if (qs.has("wait")) {
      // 场记板：纯白画面，录屏开始后调用 window.__demoGo() 才开始，白→黑的跳变用来精确对齐配音
      const slate = Object.assign(document.createElement("div"), { style: "position:fixed;inset:0;z-index:100;background:#fff" });
      document.body.appendChild(slate);
      window.__demoReady = true;
      await new Promise((r) => (window.__demoGo = r));
      slate.remove();
    }
    tour(T.list || []).catch((e) => { console.error(e); window.__demoDone = "error: " + e.message; });
  }, { once: true });
})();
